import assert from 'node:assert/strict';
import test from 'node:test';
import {
  CALCULATION_DELTA_PROTOCOL,
  CALCULATION_DELTA_VERSION,
  FormulaEngine,
  consumeCalculationSession,
  installBrowserCalculationWorkerEntry,
  type CalculationBrowserWorker,
  type CalculationSessionRequest,
  type CalculationSessionResult,
} from './index';

test('persistent calculation worker opens once and applies only canonical deltas afterwards', async () => {
  const engine = new FormulaEngine({ defaultSheetId: 'Sheet1', recalculationMode: 'manual' });
  engine.setValue('A1', 2);
  engine.setFormula('B1', '=A1*3');
  const worker = new ImmediateCalculationWorker();
  const port = engine.createCalculationSessionPort({ workerFactory: () => worker });

  await engine.recalculateAsync(undefined, port);
  assert.equal(worker.calculationPosts, 1);
  assert.equal(engine.getCellValue('B1'), 6);

  engine.setValue('A1', 5);
  await engine.recalculateAsync('A1', port);
  assert.equal(worker.calculationPosts, 2);
  assert.equal(engine.getCellValue('B1'), 15);
  const delta = worker.messages[1] as CalculationSessionRequest;
  assert.equal(delta.kind, 'calculation.delta');
  if (delta.kind !== 'calculation.delta') throw new Error('Expected calculation delta');
  assert.deepEqual(delta.delta.cells?.map((entry) => entry.address.row), [0]);
  port.dispose();
});

test('worker entry rejects the removed snapshot task protocol', () => {
  const result = consumeCalculationSession(new Map(), {
    protocol: 'react-sheets.formula-calculation',
    version: 1,
    taskId: 'legacy',
    kind: 'recalculate',
    revision: 1,
  });
  assert.equal(result.status, 'failed');
  assert.match(result.error?.message ?? '', /protocol/i);
});

test('worker entry retains one FormulaEngine per session and restores its handler', () => {
  const sent: CalculationSessionResult[] = [];
  const previous = () => undefined;
  const scope = new TestScope(sent, previous);
  const uninstall = installBrowserCalculationWorkerEntry(scope);
  scope.onmessage?.({ data: openRequest() });
  scope.onmessage?.({ data: deltaRequest(2, 8) });
  assert.equal(sent[0]?.status, 'completed');
  assert.equal(sent[1]?.status, 'completed');
  assert.equal(sent[1]?.report?.results.some((entry) => entry.value === 24), true);
  uninstall();
  assert.equal(scope.onmessage, previous);
});

function openRequest(): CalculationSessionRequest {
  const source = new FormulaEngine({ defaultSheetId: 'Sheet1', recalculationMode: 'manual' });
  source.setValue('A1', 2);
  source.setFormula('B1', '=A1*3');
  return {
    protocol: CALCULATION_DELTA_PROTOCOL,
    version: CALCULATION_DELTA_VERSION,
    kind: 'session.open',
    sessionId: 'session-test',
    taskId: 'task-open',
    revision: 1,
    generation: source.getCalculationGeneration(),
    bootstrap: source.exportCalculationBootstrap(),
  };
}

function deltaRequest(revision: number, value: number): CalculationSessionRequest {
  return {
    protocol: CALCULATION_DELTA_PROTOCOL,
    version: CALCULATION_DELTA_VERSION,
    kind: 'calculation.delta',
    sessionId: 'session-test',
    taskId: `task-${revision}`,
    revision,
    generation: 8,
    delta: { cells: [{ kind: 'set-value', address: { sheetId: 'Sheet1', row: 0, column: 0 }, value }] },
    roots: [{ sheetId: 'Sheet1', row: 0, column: 0 }],
  };
}

abstract class BaseCalculationWorker implements CalculationBrowserWorker {
  private readonly listeners = {
    message: new Set<(event: { readonly data?: unknown; readonly message?: string }) => void>(),
    error: new Set<(event: { readonly data?: unknown; readonly message?: string }) => void>(),
    messageerror: new Set<(event: { readonly data?: unknown; readonly message?: string }) => void>(),
  };

  abstract postMessage(message: unknown): void;

  terminate(): void { for (const listeners of Object.values(this.listeners)) listeners.clear(); }
  addEventListener(type: 'message' | 'error' | 'messageerror', listener: (event: { readonly data?: unknown; readonly message?: string }) => void): void { this.listeners[type].add(listener); }
  removeEventListener(type: 'message' | 'error' | 'messageerror', listener: (event: { readonly data?: unknown; readonly message?: string }) => void): void { this.listeners[type].delete(listener); }
  protected emit(type: 'message' | 'error' | 'messageerror', event: { readonly data?: unknown; readonly message?: string }): void { for (const listener of this.listeners[type]) listener(event); }
}

class ImmediateCalculationWorker extends BaseCalculationWorker {
  calculationPosts = 0;
  readonly messages: unknown[] = [];
  private readonly sessions = new Map<string, FormulaEngine>();
  postMessage(message: unknown): void {
    if (!isCalculationMessage(message)) return;
    this.calculationPosts += 1;
    this.messages.push(structuredClone(message));
    queueMicrotask(() => this.emit('message', { data: consumeCalculationSession(this.sessions, message) }));
  }
}

class TestScope {
  onmessage: ((event: { readonly data: unknown }) => void) | null;
  constructor(private readonly sent: CalculationSessionResult[], previous: () => void) {
    this.onmessage = previous;
  }
  postMessage(message: CalculationSessionResult): void { this.sent.push(message); }
  terminate(): void {}
}

function isCalculationMessage(value: unknown): boolean {
  return typeof value === 'object' && value !== null && 'kind' in value && ((value as { kind?: unknown }).kind === 'session.open' || (value as { kind?: unknown }).kind === 'calculation.delta');
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { FormulaEngine } from './formula-engine';
import { normalizeDefinedNames, resolveDefinedNameSource } from './defined-names';

test('normalizeDefinedNames uppercases keys', () => {
  assert.deepEqual(normalizeDefinedNames({ TaxRate: '0.15' }), { TAXRATE: '0.15' });
});

test('resolveDefinedNameSource supports scalar, range, and formula values', () => {
  const context = {
    currentCell: { sheetId: 'Sheet1', row: 4, column: 2 },
    readCell: (address: { row: number; column: number }) => (address.row === 0 && address.column === 0 ? 10 : null),
    readRangeMatrix: () => [[1, 2], [3, 4]],
  };
  assert.equal(resolveDefinedNameSource('0.25', context), 0.25);
  assert.deepEqual(resolveDefinedNameSource('A1:B2', context), [[1, 2], [3, 4]]);
  assert.equal(resolveDefinedNameSource('=A1+5', context), 15);
});

test('FormulaEngine resolves defined names in formulas with current cell context', () => {
  const engine = new FormulaEngine({ defaultSheetId: 'Sheet1' });
  engine.setDefinedNames({ TaxRate: '0.1', BaseCell: 'C3' });
  engine.setValue('C3', 100);
  engine.setFormula('D3', '=BaseCell*TaxRate');
  assert.equal(engine.getCellValue('D3'), 10);
});

test('FormulaEngine recalculates formulas when a defined name changes', () => {
  const engine = new FormulaEngine({ defaultSheetId: 'Sheet1' });
  engine.setDefinedNames({ Rate: '2' });
  engine.setValue('A1', 5);
  engine.setFormula('B1', '=A1*Rate');
  assert.equal(engine.getCellValue('B1'), 10);
  engine.setDefinedNames({ Rate: '3' });
  assert.equal(engine.getCellValue('B1'), 15);
});

test('FormulaEngine resolves sheet-scoped names before workbook-scoped names', () => {
  const engine = new FormulaEngine({ defaultSheetId: 'Sheet1' });
  engine.setDefinedNameModels([
    { name: 'Rate', formula: '2', scope: 'workbook' },
    { name: 'Rate', formula: '3', scope: 'sheet', sheetId: 'Sheet2' },
  ]);
  engine.setFormula({ sheetId: 'Sheet1', row: 0, column: 0 }, '=Rate');
  engine.setFormula({ sheetId: 'Sheet2', row: 0, column: 0 }, '=Rate');
  assert.equal(engine.getCellValue({ sheetId: 'Sheet1', row: 0, column: 0 }), 2);
  assert.equal(engine.getCellValue({ sheetId: 'Sheet2', row: 0, column: 0 }), 3);
});

test('scoped names survive the persistent calculation bootstrap boundary', () => {
  const engine = new FormulaEngine({ defaultSheetId: 'Sheet1', recalculationMode: 'manual' });
  engine.setDefinedNameModels([
    { name: 'Rate', formula: '2', scope: 'workbook' },
    { name: 'Rate', formula: '4', scope: 'sheet', sheetId: 'Sheet2' },
  ]);
  engine.setFormula({ sheetId: 'Sheet2', row: 0, column: 0 }, '=Rate');
  const restored = FormulaEngine.fromCalculationBootstrap(engine.exportCalculationBootstrap());
  restored.executeCalculationDelta({
    protocol: 'react-sheets.formula-delta',
    version: 1,
    kind: 'calculation.delta',
    sessionId: 'scoped-name-session',
    taskId: 'scoped-name-delta',
    revision: 1,
    generation: 1,
    delta: {},
    forceRecalculate: true,
  });
  assert.equal(restored.getCellValue({ sheetId: 'Sheet2', row: 0, column: 0 }), 4);
});

test('FormulaEngine recalculates volatile formulas when dependencies change', () => {
  const engine = new FormulaEngine({ defaultSheetId: 'Sheet1' });
  engine.setFormula('A1', '=RAND()');
  const first = engine.getCellValue('A1');
  const second = engine.getCellValue('A1');
  assert.equal(first, second);
  engine.setValue('B1', 1);
  const third = engine.getCellValue('A1');
  assert.notEqual(second, third);
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { normalizeExternalFormula } from './external-formula-normalizer';

test('normalizes Excel and WPS function namespaces without rewriting string literals', () => {
  assert.equal(normalizeExternalFormula('=_xlfn.FILTER(_xlws.A1:A3,B1:B3=1)'), '=FILTER(A1:A3,B1:B3=1)');
  assert.equal(normalizeExternalFormula('="_xlfn.FILTER"&_xlfn.UNIQUE(A1:A3)'), '="_xlfn.FILTER"&UNIQUE(A1:A3)');
});

test('normalizes the legacy SINGLE spelling into the canonical implicit-intersection operator', () => {
  assert.equal(normalizeExternalFormula('=_xlfn.SINGLE(A1)'), '=@(A1)');
  assert.equal(normalizeExternalFormula('=@A1'), '=@A1');
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { FormulaEngine, evaluateFormulaWithTrace, parseFormula } from './index';

test('formula trace evaluates real AST nodes in order', () => {
  const engine = new FormulaEngine({ defaultSheetId: 'Sheet1' });
  engine.setValue('A1', 2);
  engine.setValue('A2', 3);
  engine.setFormula('B1', '=SUM(A1:A2)*2');

  const trace = engine.evaluateFormulaWithTrace('B1');
  assert.ok(trace);
  assert.equal(trace?.value, 10);
  assert.ok((trace?.steps.length ?? 0) >= 5);
  assert.equal(trace?.steps.at(-1)?.expression, '=SUM(A1:A2)*2');

  const standalone = evaluateFormulaWithTrace(parseFormula('=A1+2'), {
    currentCell: { sheetId: 'Sheet1', row: 0, column: 1 },
    readCell: () => 3,
    readRange: () => [],
  });
  assert.equal(standalone.value, 5);
  assert.equal(standalone.steps.at(-1)?.value, 5);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { FormulaEngine } from '../formula-engine';
import { isArrayValue, isFormulaError } from '../values';

test('dynamic array functions: FILTER UNIQUE SORT SEQUENCE', () => {
  const engine = new FormulaEngine({ defaultSheetId: 'Sheet1' });
  engine.setValue('A1', 'East');
  engine.setValue('A2', 'West');
  engine.setValue('A3', 'East');
  engine.setValue('B1', 100);
  engine.setValue('B2', 200);
  engine.setValue('B3', 50);
  engine.setValue('C1', true);
  engine.setValue('C2', false);
  engine.setValue('C3', true);

  const filtered = engine.setFormula('D1', '=FILTER(A1:B3, C1:C3)').value;
  assert.ok(isArrayValue(filtered));
  assert.equal((filtered as unknown[][]).length, 2);

  const unique = engine.setFormula('E1', '=UNIQUE(A1:A3)').value;
  assert.ok(isArrayValue(unique));
  assert.equal((unique as unknown[][]).length, 2);

  const sorted = engine.setFormula('F1', '=SORT(A1:B3, 2, -1)').value;
  assert.ok(isArrayValue(sorted));
  assert.equal((sorted as unknown[][])[0]?.[1], 200);

  const sequence = engine.setFormula('G1', '=SEQUENCE(2, 3, 1, 1)').value;
  assert.ok(isArrayValue(sequence));
  assert.deepEqual(sequence, [
    [1, 2, 3],
    [4, 5, 6],
  ]);
});

test('dynamic array functions: XMATCH HSTACK VSTACK TAKE DROP', () => {
  const engine = new FormulaEngine({ defaultSheetId: 'Sheet1' });
  engine.setValue('A1', 'Alpha');
  engine.setValue('A2', 'Beta');
  engine.setValue('A3', 'Gamma');
  engine.setValue('B1', 10);
  engine.setValue('B2', 20);
  engine.setValue('C1', 1);
  engine.setValue('C2', 2);

  assert.equal(engine.setFormula('D1', '=XMATCH("Beta", A1:A3, 0)').value, 2);
  assert.equal(engine.setFormula('D2', '=XMATCH(15, B1:B2, 1)').value, 2);

  const stacked = engine.setFormula('E1', '=HSTACK(A1:A2, B1:B2)').value;
  assert.ok(isArrayValue(stacked));
  assert.deepEqual(stacked, [
    ['Alpha', 10],
    ['Beta', 20],
  ]);

  const vstacked = engine.setFormula('F1', '=VSTACK(C1:C2, B1:B2)').value;
  assert.ok(isArrayValue(vstacked));
  assert.equal((vstacked as unknown[][]).length, 4);

  const taken = engine.setFormula('G1', '=TAKE(A1:B3, 2)').value;
  assert.ok(isArrayValue(taken));
  assert.equal((taken as unknown[][]).length, 2);

  const dropped = engine.setFormula('H1', '=DROP(A1:B3, 1)').value;
  assert.ok(isArrayValue(dropped));
  assert.equal((dropped as unknown[][]).length, 2);
});

test('dynamic array functions: SORTBY and RANDARRAY', () => {
  const engine = new FormulaEngine({ defaultSheetId: 'Sheet1' });
  engine.setSpillEnvironment('Sheet1', { rowCount: 10, columnCount: 10, isOccupied: () => false });
  engine.setValue('A1', 'b');
  engine.setValue('A2', 'a');
  engine.setValue('B1', 2);
  engine.setValue('B2', 1);

  const sorted = engine.setFormula('C1', '=SORTBY(A1:A2,B1:B2)').value;
  assert.ok(isArrayValue(sorted));
  assert.equal((sorted as unknown[][])[0]?.[0], 'a');

  const random = engine.setFormula('D1', '=RANDARRAY(2,2,1,9,1)').value;
  assert.ok(isArrayValue(random));
  assert.equal((random as unknown[][]).length, 2);
});

test('dynamic array functions: FILTER empty uses if_empty', () => {
  const engine = new FormulaEngine();
  engine.setValue('A1', 1);
  engine.setValue('B1', false);
  const result = engine.setFormula('C1', '=FILTER(A1, B1, "none")').value;
  assert.deepEqual(result, [['none']]);
});

test('dynamic array functions: FILTER no match returns #CALC!', () => {
  const engine = new FormulaEngine();
  engine.setValue('A1', 1);
  engine.setValue('B1', false);
  const result = engine.setFormula('C1', '=FILTER(A1, B1)').value;
  assert.ok(isFormulaError(result));
  if (!isFormulaError(result)) throw new Error('expected error');
  assert.equal(result.code, '#CALC!');
});

test('generated dynamic arrays accept output at the cell limit', () => {
  const engine = new FormulaEngine();
  const sequence = engine.setFormula('A1', '=SEQUENCE(1000,100)').value;
  assert.ok(isArrayValue(sequence));
  assert.equal(sequence.length, 1000);
  assert.equal(sequence[0]?.length, 100);
});

test('generated dynamic arrays reject output above the cell limit before allocation', () => {
  const engine = new FormulaEngine();
  for (const formula of ['=SEQUENCE(100000000,100000000)', '=RANDARRAY(100000000,100000000)']) {
    const result = engine.setFormula('A1', formula).value;
    assert.ok(isFormulaError(result));
    if (!isFormulaError(result)) throw new Error('expected error');
    assert.equal(result.code, '#VALUE!');
    assert.match(result.message ?? '', /output exceeds the 100000-cell limit/);
  }
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { FormulaEngine } from '../index';
import { getBuiltinFunction } from './index';
import { isFormulaError } from '../values';

test('GROUPBY is enabled by default and aggregates multiple field and value columns deterministically', () => {
  const groupBy = getBuiltinFunction('GROUPBY');
  assert.ok(groupBy);

  const result = groupBy!([
    [['East', 'A'], ['East', 'A'], ['West', 'A'], ['East', 'B']],
    [[10, 1], [20, 2], [5, 3], [7, 4]],
    'SUM',
  ]);

  assert.deepEqual(result, [
    ['East', 'A', 30, 3],
    ['West', 'A', 5, 3],
    ['East', 'B', 7, 4],
  ]);
});

test('GROUPBY supports the five deterministic aggregations and treats blanks as non-numeric', () => {
  const groupBy = getBuiltinFunction('GROUPBY');
  assert.ok(groupBy);
  const fields = [['A'], ['A'], ['B'], ['B'], ['C']];
  const values = [[10], [null], [5], ['ignored'], [null]];

  assert.deepEqual(groupBy!([fields, values, 'SUM']), [['A', 10], ['B', 5], ['C', 0]]);
  assert.deepEqual(groupBy!([fields, values, 'COUNT']), [['A', 1], ['B', 1], ['C', 0]]);
  assert.deepEqual(groupBy!([fields, values, 'MIN']), [['A', 10], ['B', 5], ['C', 0]]);
  assert.deepEqual(groupBy!([fields, values, 'MAX']), [['A', 10], ['B', 5], ['C', 0]]);
  assert.deepEqual(groupBy!([fields, values, 1]), [['A', 10], ['B', 5], ['C', 0]]);

  const average = groupBy!([fields, values, 'AVERAGE']);
  assert.equal(Array.isArray(average), true);
  if (!Array.isArray(average)) throw new Error('Expected a matrix');
  assert.equal(average[0]?.[1], 10);
  assert.equal(average[1]?.[1], 5);
  assert.equal(isFormulaError(average[2]?.[1]), true);
});

test('GROUPBY uses typed keys and combines null with empty text as one blank group', () => {
  const groupBy = getBuiltinFunction('GROUPBY');
  assert.ok(groupBy);
  const result = groupBy!([
    [[null], [''], [1], ['1']],
    [[2], [3], [5], [7]],
    'SUM',
  ]);
  assert.deepEqual(result, [
    [null, 5],
    [1, 5],
    ['1', 7],
  ]);
});

test('GROUPBY validates shapes and propagates input errors instead of truncating or coercing rows', () => {
  const groupBy = getBuiltinFunction('GROUPBY');
  assert.ok(groupBy);
  const mismatch = groupBy!([[['A'], ['B']], [[1]], 'SUM']);
  assert.equal(isFormulaError(mismatch), true);
  if (!isFormulaError(mismatch)) throw new Error('Expected a shape error');
  assert.equal(mismatch.code, '#VALUE!');

  const sourceError = { kind: 'error' as const, code: '#REF!' as const, message: 'deleted' };
  const propagated = groupBy!([[['A']], [[sourceError]], 'SUM']);
  assert.deepEqual(propagated, sourceError);

  const unsupported = groupBy!([[['A']], [[1]], 'MEDIAN']);
  assert.equal(isFormulaError(unsupported), true);
  if (!isFormulaError(unsupported)) throw new Error('Expected an aggregate error');
  assert.equal(unsupported.code, '#VALUE!');
});

test('PIVOTBY builds stable row/column field headers and cross-aggregates every matching source row', () => {
  const pivotBy = getBuiltinFunction('PIVOTBY');
  assert.ok(pivotBy);

  const result = pivotBy!([
    [['East'], ['East'], ['West'], ['East']],
    [['Q1'], ['Q2'], ['Q1'], ['Q1']],
    [[100], [200], [50], [25]],
    'SUM',
  ]);

  assert.deepEqual(result, [
    [null, 'Q1', 'Q2'],
    ['East', 125, 200],
    ['West', 50, 0],
  ]);
});

test('PIVOTBY preserves multi-field and multi-value dimensions without stringifying keys', () => {
  const pivotBy = getBuiltinFunction('PIVOTBY');
  assert.ok(pivotBy);

  const result = pivotBy!([
    [['East', 2025], ['East', 2025], ['West', 2025]],
    [['Q1', true], ['Q2', true], ['Q1', true]],
    [[10, 1], [20, 2], [5, 3]],
    'SUM',
  ]);

  assert.deepEqual(result, [
    [null, null, 'Q1', 'Q1', 'Q2', 'Q2'],
    [null, null, true, true, true, true],
    [null, null, 'SUM 1', 'SUM 2', 'SUM 1', 'SUM 2'],
    ['East', 2025, 10, 1, 20, 2],
    ['West', 2025, 5, 3, 0, 0],
  ]);
});

test('PIVOTBY rejects mismatched input heights and unsupported optional arguments', () => {
  const pivotBy = getBuiltinFunction('PIVOTBY');
  assert.ok(pivotBy);
  const mismatch = pivotBy!([[['East'], ['West']], [['Q1']], [[1], [2]], 'SUM']);
  assert.equal(isFormulaError(mismatch), true);
  if (!isFormulaError(mismatch)) throw new Error('Expected a shape error');
  assert.equal(mismatch.code, '#VALUE!');

  const unsupported = pivotBy!([[['East']], [['Q1']], [[1]], 'SUM', 3]);
  assert.equal(isFormulaError(unsupported), true);
  if (!isFormulaError(unsupported)) throw new Error('Expected an unsupported-arity error');
  assert.equal(unsupported.code, '#VALUE!');
});

test('FormulaEngine accepts bare aggregate identifiers, spills GROUPBY, and computes PIVOTBY by default', () => {
  const engine = new FormulaEngine({ defaultSheetId: 'Sheet1' });
  engine.setSpillEnvironment('Sheet1', { rowCount: 20, columnCount: 12, isOccupied: () => false });
  engine.setValue('A1', 'East');
  engine.setValue('A2', 'East');
  engine.setValue('A3', 'West');
  engine.setValue('B1', 10);
  engine.setValue('B2', 20);
  engine.setValue('B3', 5);
  engine.setValue('C1', 'Q1');
  engine.setValue('C2', 'Q2');
  engine.setValue('C3', 'Q1');

  const grouped = engine.setFormula('E1', '=GROUPBY(A1:A3,B1:B3,SUM)').value;
  assert.deepEqual(grouped, [['East', 30], ['West', 5]]);
  assert.equal(engine.getSpillsForSheet('Sheet1')[0]?.state, 'ok');

  const pivoted = engine.setFormula('H1', '=PIVOTBY(A1:A3,C1:C3,B1:B3,COUNT)').value;
  assert.deepEqual(pivoted, [
    [null, 'Q1', 'Q2'],
    ['East', 1, 1],
    ['West', 1, 0],
  ]);
});

import { strict as assert } from 'node:assert';
import { test } from 'node:test';
import { FormulaEngine } from '../formula-engine';
import { isFormulaError } from '../values';

test('SJS.TABLE returns a dynamic array without writing result cells', () => {
  const engine = new FormulaEngine({ defaultSheetId: 'Sheet1' });
  engine.setFormula('C1', '=B1*2');
  engine.setValue('A2', 3);
  engine.setValue('A3', 4);
  engine.setFormula('D1', '=SJS.TABLE(C1,A2:A3,B1)');
  engine.setValue('B1', 2);
  engine.recalculate();

  assert.deepEqual(engine.getCellValue('D1'), [[6], [8]]);
  assert.equal(engine.getCellValue('D2'), null);
});

test('SJS.TABLE rejects non-paired input arguments', () => {
  const engine = new FormulaEngine({ defaultSheetId: 'Sheet1' });
  engine.setFormula('D1', '=SJS.TABLE(C1,A2:A3)');

  const result = engine.getCellValue('D1');
  assert.equal(isFormulaError(result), true);
  if (!isFormulaError(result)) throw new Error('Expected SJS.TABLE to return a formula error');
  assert.equal(result.code, '#VALUE!');
});

import assert from 'node:assert/strict';
import test from 'node:test';
import {
  FormulaEngine,
  FUNCTION_CAPABILITY_MATRIX,
  getFunctionCapability,
  RangeIndex,
  formatFormula,
  formatCellAddress,
  isFormulaError,
  lexFormula,
  parseCellAddress,
  parseFormula,
  offsetAst,
  type CellAddress,
  type FormulaValue,
} from './index';

test('lexer and parser produce a precedence-aware AST without executable code', () => {
  const tokens = lexFormula('=Sheet1!$A$1:Sheet1!B2');
  assert.deepEqual(tokens.map((token) => token.kind), [
    'identifier',
    'bang',
    'identifier',
    'colon',
    'identifier',
    'bang',
    'identifier',
    'eof',
  ]);

  const ast = parseFormula('=1 + 2 * (3 - 1)');
  assert.equal(ast.type, 'binary-expression');
  if (ast.type !== 'binary-expression') throw new Error('Expected binary AST');
  assert.equal(ast.operator, '+');
  assert.equal(ast.right.type, 'binary-expression');
  assert.equal(parseFormula('"line\\nvalue"').type, 'string-literal');
});

test('spill and implicit-intersection references round-trip and offset through the AST', () => {
  assert.deepEqual(lexFormula('=SUM(A2#)').map((token) => token.kind), [
    'identifier', 'left-paren', 'identifier', 'spill-operator', 'right-paren', 'eof',
  ]);
  assert.equal(formatFormula(parseFormula('=SUM(A2#)')), '=SUM(A2#)');
  assert.equal(formatFormula(offsetAst(parseFormula('=SUM(A2#)'), 1, 1)), '=SUM(B3#)');
