test('FormulaEngine recalculates a dependency chain and updates replaced dependencies', () => {
  const engine = new FormulaEngine();
  engine.setFormula('B1', '=A1 + 1');
  engine.setFormula('C1', '=B1 * 2');
  engine.setValue('A1', 4);
