  const propagated = engine.setFormula('B1', '=A1 + 1').value;
  const stringArithmetic = engine.setFormula('C1', '="text" + 1').value;
  const unknownFunction = engine.setFormula('D1', '=NO_SUCH_FUNCTION(1)').value;
